  Here is the Terraform HCL program that configures a query log for Route 53:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "aws_route53_example_com"
}

resource "aws_cloudwatch_log_resource_policy" "route53-query-logging-policy" {
  name = "route53-query-logging-policy"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "logs:CreateLogStream",
      "Resource": "arn:aws:logs:us-east-1:123456789012:log-group:aws_route53_example_com:log-stream:*"
    },
    {
      "Effect": "Allow",
      "Action": "logs:PutLogEvents",
      "Resource": "arn:aws:logs:us-east-1:123456789012:log-group:aws_route53_example_com:log-stream:*"
    }
  ]
}
EOF
}

resource "aws_route53_query_log" "example" {
  zone_id = aws_route53_zone.primary.id
  log_group_name = aws_cloudwatch_log_group.aws_route53_example_com.name
  log_resource_policy_name = aws_cloudwatch_log_resource_policy.route53-query-logging-policy.name
}
```
This Terraform program creates a Route 53 zone named "example.com", a CloudWatch log group named "aws_route53_example_com", and a CloudWatch log resource policy named "route53-query-logging-policy". The log resource policy allows the Route 53 zone to create log streams and put log events in the log group. The Terraform program then creates a Route 53 query log that uses the log group and log resource policy to log queries for the zone.

