provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "main" {
  name = "main.example.com"
}

resource "aws_route53_record" "primary" {
  zone_id = aws_route53_zone.main.id
  name    = "primary.main.example.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.0.1"]
}

resource "aws_route53_record" "replica-1" {
  zone_id = aws_route53_zone.main.id
  name    = "replica-1.main.example.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.0.2"]
}

resource "aws_route53_record" "replica-2" {
  zone_id = aws_route53_zone.main.id
  name    = "replica-2.main.example.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.0.3"]
}

resource "aws_route53_record" "weighted-routing-policy" {
  zone_id = aws_route53_zone.main.id
  name    = "weighted-routing-policy.main.example.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.0.1", "10.0.0.2", "10.0.0.3"]
  weighted_routing_policy {
    weight = 1
  }
  weighted_routing_policy {
    weight = 2
  }
  weighted_routing_policy {
    weight = 3
  }
}
```
