```
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "main" {
  name = "example.com"
}

resource "aws_route53_record" "eb_env" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "eb-env.example.com"
  type    = "A"

  alias {
    name                   = "eb-env.elasticbeanstalk.com"
    zone_id                = "Z3AADJGX6KTTL2"
    evaluate_target_health = true
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_s3_bucket" "examplebucket" {
  bucket = "examplebucket"
  acl    = "private"

  tags = {
    Name = "Example Bucket"
  }
}

resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.examplebucket.id
  key    = "examplebucket_object"
  source = "examplebucket_object.zip"
  etag   = filemd5("examplebucket_object.zip")
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  description = "My Elastic Beanstalk Application Version"

  source_bundle {
    s3_bucket = aws_s3_bucket.examplebucket.id
    s3_key    = aws_s3_bucket_object.examplebucket_object.key
  }
}

resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  application_version = aws_elastic_beanstalk_application_version.version.name
  instance_type       = "t2.micro"
  iam_instance_profile = aws_iam_instance_profile.eb_ec2_profile.name

  tags = {
    Name = "EB Environment"
  }
}
```
