```
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "web_app_role" {
  name = "web_app_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

