  name = "web_app_profile"
  role = aws_iam_role.web_app_role.name
}

resource "aws_vpc" "web_app_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_internet_gateway" "web_app_igw" {
  vpc_id = aws_vpc.web_app_vpc.id
}

resource "aws_subnet" "web_app_subnet_1" {
  cidr_block = "10.0.1.0/24"
  vpc_id = aws_vpc.web_app_vpc.id
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "web_app_subnet_2" {
  cidr_block = "10.0.2.0/24"
  vpc_id = aws_vpc.web_app_vpc.id
  availability_zone = "us-east-1b"
}

resource "aws_route_table" "web_app_route_table" {
  vpc_id = aws_vpc.web_app_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.web_app_igw.id
  }
}

resource "aws_route_table_association" "web_app_route_table_association_1" {
  subnet_id = aws_subnet.web_app_subnet_1.id
  route_table_id = aws_route_table.web_app_route_table.id
}

resource "aws_route_table_association" "web_app_route_table_association_2" {
  subnet_id = aws_subnet.web_app_subnet_2.id
  route_table_id = aws_route_table.web_app_route_table.id
}

resource "aws_elastic_beanstalk_environment" "web_app_env" {
  name = "web-app-env"
  application = "web-app"
  solution_stack_name = "64bit Amazon Linux 2 v3.2.10 running Node.js 14"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name = "IamInstanceProfile"
    value = aws_iam_instance_profile.web_app_profile.name
  }

