provider "aws" {
  region = "us-east-1"
}

resource "aws_instance" "blue" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.blue.id]
  subnet_id = aws_subnet.blue.id
  key_name = "my-key"

  tags = {
    Name = "blue-instance"
  }
}

resource "aws_instance" "green" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.green.id]
  subnet_id = aws_subnet.green.id
  key_name = "my-key"

  tags = {
    Name = "green-instance"
  }
}

resource "aws_security_group" "blue" {
  name        = "blue-sg"
  description = "Security group for blue environment"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "blue-sg"
  }
}

resource "aws_security_group" "green" {
  name        = "green-sg"
  description = "Security group for green environment"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "green-sg"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "blue" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.main.id

  tags = {
    Name = "blue-subnet"
  }
}

resource "aws_subnet" "green" {
  cidr_block = "10.0.2.0/24"
  vpc_id     = aws_vpc.main.id

  tags = {
    Name = "green-subnet"
  }
}

resource "aws_db_instance" "myapp_db" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = "mysql"
  engine_version       = "5.7"
  instance_class       = "db.t2.micro"
  name                 = "myapp_db"
  username             = "myapp_user"
  password             = "myapp_password"
  parameter_group_name = "default.mysql5.7"
  skip_final_snapshot  = true

  tags = {
    Name = "myapp_db"
  }
}

resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.myapp.id
  name    = "blue.myapp.com"
  type    = "A"

  alias {
    name                   = aws_elb.blue.dns_name
    zone_id                = aws_elb.blue.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.myapp.id
  name    = "green.myapp.com"
  type    = "A"

  alias {
    name                   = aws_elb.green.dns_name
    zone_id                = aws_elb.green.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_zone" "myapp" {
  name = "myapp.com"
}

resource "aws_elb" "blue" {
  name               = "blue-elb"
  availability_zones = ["us-east-1a", "us-east-1b"]
  security_groups    = [aws_security_group.blue.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    target              = "HTTP:80/"
    interval            = 30
  }

  tags = {
    Name = "blue-elb"
  }
}

resource "aws_elb" "green" {
  name               = "green-elb"
  availability_zones = ["us-east-1a", "us-east-1b"]
  security_groups    = [aws_security_group.green.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    target              = "HTTP:80/"
    interval            = 30
  }

  tags = {
    Name = "green-elb"
  }
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": "sts:AssumeRole",
      "Principal": {
        "Service": "ec2.amazonaws.com"
      },
      "Effect": "Allow",
      "Sid": ""
    }
  ]
}
EOF
}
