This Terraform program will create an AWS Lex bot for ordering pizzas with 5 different intents. The bot will be deployed in the us-west-2 region and will use the AWS Lex V2 API. The bot will have 5 different intents, each with a different set of utterances and responses. The bot will also have a fallback intent that will be triggered if the user's utterance does not match any of the other intents.

Here is the Terraform HCL program:
```
provider "aws" {
  region = "us-west-2"
}

resource "aws_lex_bot" "pizza_bot" {
  name = "PizzaBot"
  description = "A bot for ordering pizzas"
  intents {
    name = "OrderPizza"
    utterances = [
      "I want to order a pizza",
      "Can you help me order a pizza?",
      "I'd like to order a pizza, please",
      "I'd like to order a pizza with [toppings]",
      "I'd like to order a [size] pizza with [toppings]",
    ]
    responses {
      message = "Sure, I can help you with that. What size pizza would you like?"
      response_card = "size"
    }
  }
  intents {
    name = "Size"
    utterances = [
      "I'd like a [size] pizza",
      "I'd like a [size] pizza with [toppings]",
    ]
    responses {
      message = "Great, you've chosen a [size] pizza. What toppings would you like?"
      response_card = "toppings"
    }
  }
  intents {
    name = "Toppings"
    utterances = [
      "I'd like [toppings] on my pizza",
      "I'd like [toppings] on my [size] pizza",
    ]
    responses {
      message = "Okay, you've chosen [toppings]. Would you like any sauce or cheese?"
      response_card = "sauce_cheese"
    }
  }
  intents {
    name = "SauceCheese"
    utterances = [
      "I'd like [sauce] and [cheese] on my pizza",
      "I'd like [sauce] and [cheese] on my [size] pizza",
    ]
    responses {
      message = "Alright, you've chosen [sauce] and [cheese]. Is there anything else you'd like to add?"
      response_card = "additional_toppings"
    }
  }
  intents {
    name = "AdditionalToppings"
    utterances = [
      "I'd like [additional_toppings] on my pizza",
      "I'd like [additional_toppings] on my [size] pizza",
    ]
    responses {
      message = "Okay, you've chosen [additional_toppings]. Is there anything else you'd like to add?"
      response_card = "additional_toppings"
    }
  }
  intents {
    name = "Fallback"
    utterances = [
      "I'd like to order a pizza with [toppings]",
      "I'd like to order a [size] pizza with [toppings]",
    ]
    responses {
      message = "Sorry, I didn't understand that. Can you please rephrase your question?"
      response_card = "fallback"
    }
  }
}
```
