  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "eks:*",
      "Resource": "*"
    }
  ]
}
EOF
    }
  ]
}

data "aws_eks_cluster" "my-cluster" {
  name = module.eks.cluster_name
}

data "aws_eks_cluster_auth" "my-cluster" {
  name = module.eks.cluster_name
}

provider "helm" {
