    host = data.aws_eks_cluster.my-cluster.endpoint
    token = data.aws_eks_cluster_auth.my-cluster.token
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.my-cluster.certificate_authority.data)
  }
}

provider "kubernetes" {
  host = data.aws_eks_cluster.my-cluster.endpoint
  token = data.aws_eks_cluster_auth.my-cluster.token
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.my-cluster.certificate_authority.data)
}
