    volume_size = 50
    volume_type = "gp2"
  }
}

resource "aws_security_group" "custom_sg" {
  name = "custom_sg"
  description = "Custom security group"
  vpc_id = aws_vpc.custom_vpc.id

  ingress {
    from_port = 22
    to_port = 22
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port = 443
    to_port = 443
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

