```
provider "aws" {
  region = "us-east-1"
}

resource "aws_subnet" "subnet_us_east_1a" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_us_east_1b" {
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_instance" "instance_us_east_1a" {
  ami = "ami-0123456789abcdef0"
  instance_type = "t2.micro"
  subnet_id = aws_subnet.subnet_us_east_1a.id

  root_block_device {
    volume_size = 50
  }
}

resource "aws_instance" "instance_us_east_1b" {
  ami = "ami-0123456789abcdef0"
  instance_type = "t2.micro"
  subnet_id = aws_subnet.subnet_us_east_1b.id

  root_block_device {
    volume_size = 50
  }
}
```
This Terraform program defines two subnets in us-east-1a and us-east-1b with the latest Amazon Linux 2 AMI instance in each with t2.micro instance type and an attached EBS volume of 50 GB. The program also defines two IAM roles, one for each instance, with the necessary permissions to create and manage the instances and their associated resources.

Note that the `ami` and `instance_type` variables are not declared in the program, so they will use the default values for those variables. Also, the `root_block_device` block is used to specify the size of the EBS volume attached to the instance.

