  To reduce the number of database calls, you can use a caching mechanism to store frequently accessed data in memory. This can be achieved using a caching library such as Redis or Memcached.

Here is an example Terraform HCL program that defines a Redis cache cluster:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id   = "redis-cluster"
  engine       = "redis"
  node_type    = "cache.t2.micro"
  num_cache_nodes = 1
  parameter_group_name = "default.redis5.0"
  port = 6379
  subnet_group_name = "redis-subnet-group"
  security_group_ids = ["sg-12345678"]
}

resource "aws_elasticache_parameter_group" "redis" {
  name = "redis-parameter-group"
  family = "redis5.0"
  parameter {
    name = "maxmemory-policy"
    value = "allkeys-lru"
  }
}

resource "aws_elasticache_subnet_group" "redis" {
  name = "redis-subnet-group"
  subnet_ids = ["subnet-12345678"]
}

resource "aws_security_group" "redis" {
  name = "redis-security-group"
  description = "Security group for Redis cluster"
  vpc_id = "vpc-12345678"

  ingress {
    from_port = 6379
    to_port = 6379
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```
This Terraform program defines a Redis cache cluster with a single node, using the `aws_elasticache_cluster` resource. The `aws_elasticache_parameter_group` resource is used to define the Redis parameter group, which sets the `maxmemory-policy` parameter to `allkeys-lru`. The `aws_elasticache_subnet_group` resource is used to define the subnet group for the Redis cluster, and the `aws_security_group` resource is used to define the security group for the Redis cluster.

Note that this is just an example Terraform program, and you will need to modify it to fit your specific use case. Additionally, you will need to ensure that the Redis cache cluster is properly configured and secured for your use case.

