This Terraform program will create an AWS CodeBuild project that will run students' code stored on GitHub in a specific environment and store the result. The program will create the following resources:

* An AWS CodeBuild project
* An AWS CodeBuild environment
* An AWS CodeBuild source location
* An AWS CodeBuild artifacts location
* An AWS IAM role for CodeBuild

The program will also create the following variables:

* `github_repo`: The GitHub repository that contains the students' code.
* `github_branch`: The branch of the GitHub repository that contains the students' code.
* `github_token`: The GitHub token that will be used to access the repository.
* `codebuild_project_name`: The name of the CodeBuild project.
* `codebuild_environment_name`: The name of the CodeBuild environment.
* `codebuild_source_location`: The location of the CodeBuild source code.
* `codebuild_artifacts_location`: The location of the CodeBuild artifacts.
* `codebuild_iam_role_name`: The name of the IAM role for CodeBuild.

The program will also create the following outputs:

* `codebuild_project_arn`: The ARN of the CodeBuild project.
* `codebuild_environment_arn`: The ARN of the CodeBuild environment.
* `codebuild_source_location_arn`: The ARN of the CodeBuild source location.
* `codebuild_artifacts_location_arn`: The ARN of the CodeBuild artifacts location.
* `codebuild_iam_role_arn`: The ARN of the IAM role for CodeBuild.

Here is the Terraform HCL program that will be defined:
```
provider "aws" {
  region = "us-east-1"
}

variable "github_repo" {
  type = string
  default = "https://github.com/my-org/my-repo"
}

variable "github_branch" {
  type = string
  default = "main"
}

variable "github_token" {
  type = string
  default = "my-github-token"
}

variable "codebuild_project_name" {
  type = string
  default = "my-codebuild-project"
}

variable "codebuild_environment_name" {
  type = string
  default = "my-codebuild-environment"
}

variable "codebuild_source_location" {
  type = string
  default = "my-codebuild-source-location"
}

variable "codebuild_artifacts_location" {
  type = string
  default = "my-codebuild-artifacts-location"
}

variable "codebuild_iam_role_name" {
  type = string
  default = "my-codebuild-iam-role"
}

resource "aws_codebuild_project" "my-codebuild-project" {
  name = var.codebuild_project_name
  description = "My CodeBuild project"
  source_location = var.codebuild_source_location
  artifacts_location = var.codebuild_artifacts_location
  environment = var.codebuild_environment_name
  iam_role = var.codebuild_iam_role_name
  github_repo = var.github_repo
  github_branch = var.github_branch
  github_token = var.github_token
}

resource "aws_codebuild_environment" "my-codebuild-environment" {
  name = var.codebuild_environment_name
  description = "My CodeBuild environment"
  compute_type = "BUILD_GENERAL1_SMALL"
  image = "aws/codebuild/standard:4.0"
  type = "LINUX_CONTAINER"
  privileged_mode = true
}

resource "aws_codebuild_source_location" "my-codebuild-source-location" {
  name = var.codebuild_source_location
  description = "My CodeBuild source location"
  type = "GITHUB"
  location = var.github_repo
  branch = var.github_branch
  token = var.github_token
}

resource "aws_codebuild_artifacts_location" "my-codebuild-artifacts-location" {
  name = var.codebuild_artifacts_location
  description = "My CodeBuild artifacts location"
  type = "S3"
  location = "s3://my-codebuild-artifacts-bucket"
}

resource "aws_iam_role" "my-codebuild-iam-role" {
  name = var.codebuild_iam_role_name
  description = "My CodeBuild IAM role"
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "codebuild.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

output "codebuild_project_arn" {
  value = aws_codebuild_project.my-codebuild-project.arn
}

output "codebuild_environment_arn" {
  value = aws_codebuild_environment.my-codebuild-environment.arn
}

output "codebuild_source_location_arn" {
  value = aws_codebuild_source_location.my-codebuild-source-location.arn
}

output "codebuild_artifacts_location_arn" {
  value = aws_codebuild_artifacts_location.my-codebuild-artifacts-location.arn
}

output "codebuild_iam_role_arn" {
  value = aws_iam_role.my-codebuild-iam-role.arn
}
```
This program will create the necessary resources to run students' code stored on GitHub in a specific environment and store the result using AWS CodeBuild. The program will also create the necessary IAM roles and outputs to access the resources.

