```
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "code_build_output" {
  bucket = "code-build-output"
  acl    = "private"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  cidr_block = "10.0.0.0/24"
  vpc_id     = aws_vpc.main.id
}

resource "aws_security_group" "main" {
  name        = "main"
  description = "Allow all outbound traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_codebuild_project" "main" {
  name          = "main"
  description   = "CodeBuild project for students"
  build_timeout = 60
  service_role  = "arn:aws:iam::123456789012:role/codebuild-service-role"

  artifacts {
    type = "S3"
    location = aws_s3_bucket.code_build_output.arn
  }

  environment {
    computer_type = "BUILD_GENERAL1_SMALL"
    image         = "alpine"
    type          = "LINUX_CONTAINER"
  }

  source {
    type      = "GITHUB"
    location  = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id = aws_vpc.main.id
    subnet_ids = [aws_subnet.main.id]
    security_group_ids = [aws_security_group.main.id]
  }
}
```
This Terraform program defines the following resources:

* An AWS S3 bucket named "code-build-output" to store code build output.
* An AWS VPC with CIDR block "10.0.0.0/16" and a VPC subnet with CIDR block "10.0.0.0/24".
* An AWS Security Group linked to the VPC, with no ingress and egress to block internet access.
* An AWS CodeBuild project resource with an artifacts argument block of type S3 to store students' code build output with location being the S3 bucket resource, an environment argument block with "BUILD_GENERAL1_SMALL" computer_type, "alpine" image, and "LINUX_CONTAINER" type, and a source argument block of "GITHUB" type, 1 git_clone_depth, and "github.com/source-location" location, and a vpc_config argument block to link to the VPC resources.

Note that the provider configuration is set to "aws" and the region is set to "us-east-1". The IAM role for the CodeBuild project is set to "arn:aws:iam::123456789012:role/codebuild-service-role".

