  To accomplish this using AWS EventBridge, we will need to create a rule that triggers a target every day at 7 UTC. The target will be an AWS Lambda function that runs the code we want to execute.

Here is the Terraform HCL program that defines this configuration:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_eventbridge_rule" "daily_rule" {
  name        = "daily-rule"
  description = "Daily rule to trigger Lambda function at 7 UTC"

  schedule_expression = "cron(0 7 * * ? *)"

  target {
    arn = aws_lambda_function.my_function.arn
  }
}

resource "aws_lambda_function" "my_function" {
  function_name = "my-function"
  runtime       = "nodejs14.x"
  handler       = "index.handler"
  role          = aws_iam_role.lambda_role.arn
  memory_size   = 128
  timeout       = 30

  environment {
    variables = {
      MY_VARIABLE = "my-value"
    }
  }
}

