  Here is a description of the Terraform program that will be defined:

This Terraform program will create the infrastructure for a video streaming site that distributes video content globally using AWS CloudFront, AWS Route53, and AWS S3. The program will create the following resources:

* An AWS CloudFront origin access control (OAC) to restrict access to the S3 bucket
* An AWS CloudFront distribution to serve the video content to users
* An AWS Route53 zone to manage DNS records for the video streaming site
* An AWS S3 record to store the video content

The program will also create the necessary IAM roles and policies to allow the CloudFront distribution to access the S3 bucket and the Route53 zone to manage DNS records.

Here is the Terraform HCL program that will be generated:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudfront_origin_access_identity" "video_streaming_site" {
  comment = "Video streaming site origin access identity"
}

resource "aws_cloudfront_distribution" "video_streaming_site" {
  origin {
    domain_name = aws_s3_bucket.video_streaming_site.bucket_domain_name
    origin_id   = "video-streaming-site"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.video_streaming_site.cloudfront_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  aliases = [
    "video-streaming-site.com",
    "www.video-streaming-site.com",
  ]

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "video-streaming-site"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "allow-all"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  price_class = "PriceClass_100"

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  tags = {
    Environment = "production"
  }
}

resource "aws_route53_zone" "video_streaming_site" {
  name = "video-streaming-site.com"
}

resource "aws_route53_record" "video_streaming_site" {
  zone_id = aws_route53_zone.video_streaming_site.zone_id
  name    = "video-streaming-site.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_site.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_site.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_s3_bucket" "video_streaming_site" {
  bucket = "video-streaming-site.com"
  acl    = "private"

  tags = {
    Name        = "Video streaming site"
    Environment = "production"
  }
}

resource "aws_s3_bucket_policy" "video_streaming_site" {
  bucket = aws_s3_bucket.video_streaming_site.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontAccess"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity ${aws_cloudfront_origin_access_identity.video_streaming_site.id}"
        }
        Action    = "s3:GetObject"
        Resource  = "arn:aws:s3:::${aws_s3_bucket.video_streaming_site.id}/*"
      },
    ]
  })
}
```
This Terraform program will create the necessary resources to deploy a video streaming site that distributes video content globally using AWS CloudFront, AWS Route53, and AWS S3. The program will create an AWS CloudFront origin access control to restrict access to the S3 bucket, an AWS CloudFront distribution to serve the video content to users, an AWS Route53 zone to manage DNS records for the video streaming site, and an AWS S3 record to store the video content. The program will also create the necessary IAM roles and policies to allow the CloudFront distribution to access the S3 bucket and the Route53 zone to manage DNS records.

