  Here is a description of the Terraform program I will define:

This Terraform program will create a video streaming site infrastructure with multiple servers to balance load using AWS Load Balancing, AWS Route53, and AWS VPC module, and AWS EC2. The program will create the following resources:

* A VPC with two subnets, one for the load balancer and one for the EC2 instances
* An internet gateway to allow traffic from the internet to the load balancer and EC2 instances
* A load balancer with a public IP address and a security group to allow traffic from the internet to the load balancer
* Two EC2 instances with a security group to allow traffic from the load balancer to the EC2 instances
* A Route53 hosted zone and record set to map a domain name to the load balancer

Here is the Terraform HCL program:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "video-streaming-vpc"
  }
}

resource "aws_subnet" "load_balancer_subnet" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "load-balancer-subnet"
  }
}

resource "aws_subnet" "ec2_subnet" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "ec2-subnet"
  }
}

resource "aws_internet_gateway" "video_streaming_igw" {
  vpc_id = aws_vpc.video_streaming_vpc.id

  tags = {
    Name = "video-streaming-igw"
  }
}

resource "aws_route_table" "video_streaming_rt" {
  vpc_id = aws_vpc.video_streaming_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.video_streaming_igw.id
  }

  tags = {
    Name = "video-streaming-rt"
  }
}

resource "aws_route_table_association" "load_balancer_rta" {
  subnet_id = aws_subnet.load_balancer_subnet.id
  route_table_id = aws_route_table.video_streaming_rt.id
}

resource "aws_route_table_association" "ec2_rta" {
  subnet_id = aws_subnet.ec2_subnet.id
  route_table_id = aws_route_table.video_streaming_rt.id
}

resource "aws_security_group" "load_balancer_sg" {
  name = "load-balancer-sg"
  description = "Allow traffic from the internet to the load balancer"
  vpc_id = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "load-balancer-sg"
  }
}

resource "aws_security_group" "ec2_sg" {
  name = "ec2-sg"
  description = "Allow traffic from the load balancer to the EC2 instances"
  vpc_id = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    security_groups = [aws_security_group.load_balancer_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

resource "aws_elb" "video_streaming_elb" {
  name = "video-streaming-elb"
  subnets = [aws_subnet.load_balancer_subnet.id]
  security_groups = [aws_security_group.load_balancer_sg.id]

  listener {
    instance_port = 80
    instance_protocol = "http"
    lb_port = 80
    lb_protocol = "http"
  }

  health_check {
    healthy_threshold = 2
    unhealthy_threshold = 2
    timeout = 3
    target = "HTTP:80/"
    interval = 30
  }

  tags = {
    Name = "video-streaming-elb"
  }
}

resource "aws_instance" "video_streaming_instance_1" {
  ami = "ami-12345678"
  instance_type = "t2.micro"
  subnet_id = aws_subnet.ec2_subnet.id
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "video-streaming-instance-1"
  }
}

resource "aws_instance" "video_streaming_instance_2" {
  ami = "ami-12345678"
  instance_type = "t2.micro"
  subnet_id = aws_subnet.ec2_subnet.id
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "video-streaming-instance-2"
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming.com"
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.id
