  Here is a description of the Terraform program that will be defined:

This Terraform program will create a video streaming site infrastructure with multiple servers to balance load. It will use the following resources:

* AWS Load Balancing
* AWS Load Balancing target group
* AWS Route53 zone
* AWS Route53 record
* AWS VPC module
* AWS VPC subnet
* AWS VPC security group
* AWS EC2 instance

The program will create a VPC with a subnet, security group, and EC2 instance. It will also create a Route53 zone and record to provide a domain name for the video streaming site. Finally, it will create a load balancer and target group to distribute traffic across the EC2 instances.

Here is the Terraform HCL program:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_security_group" "example" {
  vpc_id = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "example" {
  ami           = "ami-12345678"
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.example.id]
  subnet_id = aws_subnet.example.id
}

resource "aws_route53_zone" "example" {
  name = "example.com"
}

resource "aws_route53_record" "example" {
  zone_id = aws_route53_zone.example.id
  name    = "example.com"
  type    = "A"
  ttl     = "300"
  records = [aws_instance.example.public_ip]
}

resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.example.id]
  security_groups    = [aws_security_group.example.id]
}

resource "aws_lb_target_group" "example" {
  name     = "example-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id
}

resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example.arn
  }
}
```
