  Here is a Terraform HCL program that creates an 20GB MySQL instance on AWS with randomly generated ID and password:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_db_instance" "mysql" {
  allocated_storage    = 20
  storage_type         = "gp2"
  engine               = "mysql"
  engine_version       = "5.7"
  instance_class       = "db.t2.micro"
  name                 = "mysql-${random_id.id.hex}"
  username             = "mysql-${random_id.id.hex}"
  password             = random_password.password.result
  db_subnet_group_name = "default"
  vpc_security_group_ids = [aws_security_group.mysql.id]
  skip_final_snapshot = true
}

resource "random_id" "id" {
  byte_length = 8
}

resource "random_password" "password" {
  length = 16
  special = true
}

resource "aws_security_group" "mysql" {
  name        = "mysql-sg"
  description = "Security group for MySQL instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}
```
This Terraform program creates an AWS VPC, a security group for the MySQL instance, and a MySQL instance with a randomly generated ID and password. The MySQL instance is created in the `us-east-1` region and has a 20GB storage size. The security group allows inbound traffic on port 3306 from any IP address. The `skip_final_snapshot` parameter is set to `true` to avoid creating a final snapshot of the instance before it is terminated.

Note that this program assumes that you have the necessary permissions to create resources in the `us-east-1` region. If you are using a different region, you will need to update the `region` parameter in the `provider` block accordingly.

