  name       = "example-subnet-group"
  subnet_ids = [aws_subnet.example.id]
}

resource "aws_db_parameter_group" "example" {
  name        = "example-parameter-group"
  family      = "aurora-postgresql13"
  description = "Example PostgreSQL parameter group"

