  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_kms_key" "example" {
  description = "Example KMS key for encrypting PostgreSQL database"
}

resource "aws_rds_cluster" "example" {
  cluster_identifier = "example-cluster"
  engine             = "aurora-postgresql"
  engine_version     = "13.6"
  instance_class     = "db.t3.micro"
  multi_az           = true
  storage_encrypted  = true
  kms_key_id         = aws_kms_key.example.arn
  backup_retention_period = 7

  parameter_group {
    name = "example-parameter-group"
    parameters = {
      "max_connections" = 100
      "shared_buffers"  = 1000
    }
  }

  security_group {
    name = "example-security-group"
    ingress {
      from_port   = 5432
      to_port     = 5432
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}
```
This Terraform program defines the following resources:

* `aws_vpc`: A VPC with the specified CIDR block.
* `aws_subnet`: A subnet within the VPC with the specified CIDR block.
* `aws_kms_key`: A KMS key for encrypting the PostgreSQL database.
* `aws_rds_cluster`: A PostgreSQL database cluster with the specified engine version, instance class, and storage encryption.
* `aws_rds_cluster_parameter_group`: A custom parameter group for the PostgreSQL database cluster with the specified parameters.
* `aws_rds_cluster_security_group`: A security group for managing access to the PostgreSQL database cluster.

Note that this program assumes that the VPC and subnet have already been created, and that the KMS key has already been created and imported into the AWS account. If these resources do not exist, you will need to create them before running this program.

