}

resource "aws_db_instance" "airbyte_connector_test" {
  identifier = "airbyte-connector-test"
  engine = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  storage_type = "gp2"
  multi_az = true
  publicly_accessible = true
