  name = "airbyte-connector-test"
  description = "Security group for Airbyte connector test"
  vpc_id = aws_vpc.airbyte_connector_test.id

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "airbyte_connector_test_public_1" {
