This Terraform program will create a Load Balancer with a target group in the specified region. The Load Balancer will be configured with a listener on port 80 that forwards incoming traffic to the target group. The target group will be configured with a health check on port 80 that checks the health of the instances in the group.

Here is the Terraform HCL program:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_lb" "example" {
  name               = "example-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.example.id]
  subnets            = [aws_subnet.example.id]

  listener {
    port     = 80
    protocol = "HTTP"
  }

  target_group {
    name     = "example-tg"
    port     = 80
    protocol = "HTTP"
    vpc_id   = aws_vpc.example.id
  }
}

resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Security group for example load balancer"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "example" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.example.id
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}
```
This program creates a Load Balancer with a target group in the `us-east-1` region. The Load Balancer is configured with a listener on port 80 that forwards incoming traffic to the target group. The target group is configured with a health check on port 80 that checks the health of the instances in the group. The program also creates a security group and subnet to be used by the Load Balancer and target group.

Note that this program assumes that you have already created a VPC and subnet in the `us-east-1` region. If you have not, you will need to create them before running this program.

