  To create an AWS database that uses Managed Master Passwords via Secrets Manager with a specific KMS Key, you can use the following Terraform HCL program:
```
provider "aws" {
  region = "us-east-1"
}

resource "aws_secretsmanager_secret" "database_password" {
  name = "database_password"
  kms_key_id = "arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012"
}

resource "aws_secretsmanager_secret_version" "database_password_version" {
  secret_id = aws_secretsmanager_secret.database_password.id
  secret_string = "my_database_password"
}

resource "aws_db_instance" "example" {
  identifier = "example-db"
  engine = "mysql"
  engine_version = "5.7"
  instance_class = "db.t2.micro"
  allocated_storage = 20
  storage_type = "gp2"
  username = "my_username"
  password = aws_secretsmanager_secret_version.database_password_version.secret_string
  kms_key_id = aws_secretsmanager_secret.database_password.kms_key_id
  vpc_security_group_ids = [aws_security_group.example.id]
  db_subnet_group_name = aws_db_subnet_group.example.name
  parameter_group_name = "default.mysql5.7"
  availability_zone = "us-east-1a"
  multi_az = true
  publicly_accessible = false
  tags = {
    Name = "example-db"
  }
}

resource "aws_security_group" "example" {
  name = "example-sg"
  description = "Allow inbound traffic to the example database"
  vpc_id = "vpc-12345678"

  ingress {
    from_port = 3306
    to_port = 3306
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "example" {
  name = "example-subnet-group"
  subnet_ids = ["subnet-12345678", "subnet-87654321"]
}
```
This Terraform program creates an AWS database instance with a Managed Master Password stored in Secrets Manager, using a specific KMS Key. The program also creates a security group and a subnet group for the database instance.

Note that you will need to replace the `region` and `kms_key_id` values in the `provider` block with the appropriate values for your AWS account. You will also need to replace the `vpc_id` and `subnet_ids` values in the `aws_security_group` and `aws_db_subnet_group` resources with the appropriate values for your VPC and subnets.

